Algorithm CuadradoMagico
  Dimension m[3, 3] As Integer;
  For f <- 0 To 2 Do
    For c <- 0 To 2 Do
      Read m[f, c];
    EndFor
  EndFor
  Define objetivo As Integer <- m[0, 0] + m[0, 1] + m[0, 2];
  Define esMagico As Boolean <- True;
  For i <- 0 To 2 Do
    If m[i, 0] + m[i, 1] + m[i, 2] <> objetivo Then
      esMagico <- False;
    EndIf
    If m[0, i] + m[1, i] + m[2, i] <> objetivo Then
      esMagico <- False;
    EndIf
  EndFor
  If m[0, 0] + m[1, 1] + m[2, 2] <> objetivo Then
    esMagico <- False;
  EndIf
  If m[0, 2] + m[1, 1] + m[2, 0] <> objetivo Then
    esMagico <- False;
  EndIf
  If esMagico Then
    Write "Es mágico";
  Else
    Write "No es mágico";
  EndIf
EndAlgorithm
